  ('CMX-CORN-TORTILLA-6INCH-500G', 'Corn Tortilla, Intermex 6inch 500g', 'bulk', 20.00, 'Made with tradition in every fold, Intermex Corn Tortillas are crafted from authentic Mexican masa for the perfect texture and taste. Soft, versatile, and full of heritage, they''re the foundation of every great taco night. 🌽 Made from traditional corn masa 🌽 Soft, pliable, and easy to heat 🌽 Ideal for tacos, enchiladas, tostadas &amp; more 🌽 500 g pack – perfect for family meals or food service 🌽 Crafted by Intermex, authentic Mexican flavor in every bite. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/2_0455f02c-8a8e-4676-9787-8ad60cabf280.png?v=1750510751', 50, 'My Store', false, false),
  ('CMX-CORN-TORTILLA-4-5-1KG', 'Corn Tortilla 4.5'''' 1kg', 'bulk', 40.00, 'mexican corn tortilla taquera 4.5''''. Buy Corn Tortilla 4.5'''' 1kg in the UAE. A Mexican food for wholesale option to stock restaurant kitchens, hospitality operations or retail shelves. A practical option for restaurant kitchens, hospitality operations, catering and retail supply in the UAE. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/2_643fbaeb-ab24-4ab5-b025-13fac6b27751.png?v=1752656576', 50, 'Intermex UAE', false, false),
  ('CMX-FLOUR-TORTILLAS-PRE-COOK-500GM', 'Flour Tortillas,Pre-cook Intermex 500gm', 'bulk', 22.00, 'Soft, flexible, and melt-in-your-mouth delicious, Pre-cook with butter made from the finest ingredients, Intermex Flour Tortillas bring authentic Mexican flavor to everything from breakfast burritos to late-night quesadillas. Heat them for seconds, fill them with your favorite ingredients, and enjoy the unmistakable taste of fresh-made tortillas at home. 🌾 Crafted with premium wheat flour for ultra-soft texture 🌾 Resealable 500 g pouch to lock in freshness 🌾 Versatile, great for tacos, burritos, quesadillas &amp; wraps 🌾 Ready to heat and serve in under 30 seconds. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_08f0cc3b-3952-42a0-8969-81ef87c54cb5.png?v=1750513818', 50, 'My Store', false, false),
  ('24', 'Clamato® Original 1.89L', 'beverages', 42.00, 'Tomato Cocktail From Concentrate A must-have in any Latin kitchen, Clamato® Original blends rich tomato juice with a touch of clam broth for a savory, refreshing flavor. It’s the ultimate mixer for Micheladas , Bloody Marys , and a zesty ingredient in seafood dishes and marinades. 🥫 32 fl oz (1.89L) 🔥 50 calories per serving 🍅 Bold tomato &amp; clam flavor 🍹 Ideal for cocktails, cooking &amp; sipping 🇲🇽 Loved across Mexico and beyond. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_21b8782b-f880-412c-9615-22772133ba17.png?v=1750934791', 50, 'My Store', false, false),
  ('CMX-BANDANAS', 'Bandanas', null, 6.00, 'A timeless accessory with a cultural twist. This single paisley-print bandana is perfect for adding flair to your outfit, whether worn as a headwrap, neck scarf, wrist tie, or bag accent. Lightweight, colorful, and versatile, it''s a go-to staple for festivals, everyday style, or traditional celebrations.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_c8c868f0-8b6e-4431-8fad-b5a5e3d3de83.png?v=1750941652', 50, 'My Store', false, false),
  ('CMX-CANCUN-BANDANA-CAP', 'Cancun Bandana Cap', null, 27.00, 'Turn heads with this edgy Cancun bandana-style cap featuring a bold skull-and-crossbones print and the playful phrase “Just Another Day in Paradise.” Available in fiery red or classic black, this lightweight cap is perfect for beach days, parties, or just channeling vacation vibes wherever you are. A must-have souvenir with attitude straight from Mexico!', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_68f2981a-b910-499a-9237-466add7838db.png?v=1750943669', 50, 'My Store', false, false),
  ('CMX-VIVA-BANDANA', 'Viva Mexico Bandana', null, 6.00, 'Celebrate Mexican pride in bold style with this vibrant "Viva México" bandana. Featuring a festive sombrero design, rich green borders with ornate detailing, and a bright yellow center, it’s perfect for national holidays, themed parties, or everyday flair. Wear it, wave it, or decorate with it, this bandana brings the fiesta wherever it goes!', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_7a1083b1-f44d-4f59-a2b5-8e727ac8973c.png?v=1750943371', 50, 'My Store', false, false),
  ('CMX-MINI-ZARAPE-COASTER', 'Mini Mexican Zarape Coaster', null, 5.00, 'Add a pop of culture to your home or workspace with this handcrafted mini textile mat, featuring a classic Mexican-inspired pattern in vibrant green, earthy clay, and black. Whether used as a coaster, decorative tray liner, or mini placemat, it brings warmth, texture, and personality to any surface. Finished with fringed edges for a rustic touch.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_3691360a-1f40-41bb-8126-4dc2cd763e0a.png?v=1750942906', 50, 'My Store', false, false),
  ('CMX-MEXICANO-FLORAL-TABLE-RUNNER', 'Mexicano Floral Table Runner', null, 95.00, 'Wrap yourself in the colors of Mexico. This beautifully embroidered Table Runner bursts with vibrant florals inspired by traditional Mexican craftsmanship. Handmade with intricate detailing and bold, festive colors, it’s a perfect decoration. Hand-embroidered design Colorful floral motifs Lightweight and soft with fringe edges Each piece is unique', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_a1b16c77-de60-4fa4-9dd1-3eee202ea060.png?v=1750941902', 50, 'My Store', false, false),
  ('CMX-HEAT-RESISTANT-MAT', 'Heat-resistant mat', null, 10.00, 'Add a rustic touch to your table with this heat-resistant mat. Crafted from natural palm fibers, this heat resistant mat combine traditional Mexican weaving techniques with practical everyday use. Lightweight, durable and beautifully detailed, perfect for protecting your surfaces while adding a warm, artisan vibe to your home or party setup.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_eabf25cf-a799-4dc8-8173-4ec3d3d16274.png?v=1750940544', 50, 'My Store', false, false),
  ('2', 'Classic Mexican Straw Sombrero', null, 157.00, 'Celebrate Mexican heritage with this authentic straw sombrero, featuring the iconic red, white, and green colors of the Mexican flag. Handwoven from natural palm fibers, makes it lightweight and breathable. Perfect for fiestas, Día de Muertos festivals or just adding a fun cultural touch to your decor. A true symbol of Mexican tradition!', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_cb866611-9879-44d4-9e35-64c7b0eb6d95.png?v=1750940285', 50, 'My Store', false, false),
  ('CMX-PINATA2GO-PARTY-KIT', 'Pinata2Go Party Kit', null, 120.00, 'Bring the party to life with this ready-to-go piñata kit! Packed with vibrant colors and traditional charm, this classic star-shaped piñata is perfect for birthdays, fiestas, and family gatherings. Easy to assemble and filled with fun, it is a must-have for kids and also adults. Just hang it up, grab a stick, and let the fun begin!', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_e2004aa7-60c1-4204-83aa-e4457a2c754f.png?v=1750939801', 50, 'My Store', false, false),
  ('CMX-ALUMINUM-TORTILLA-PRESS', 'Aluminum Tortilla Press', null, 99.00, 'Traditional Mexican Tortilla Maker Make fresh, homemade tortillas the authentic way! This sturdy aluminum tortilla press, helps you shape perfectly round corn tortillas with ease. Whether you are prepping tacos, tostadas, or sopes, this kitchen essential is a quick and efficient tool that brings a touch of tradition to every meal. Just press, peel, and cook!', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_3f40e543-1a5f-4f86-91bb-a1bb7bc5f093.png?v=1750939327', 50, 'My Store', false, false),
  ('CMX-MOLCAJETE-TRADITIONAL-MORTAR-AND-PESTLE', 'Molcajete, Traditional Mexican Mortar & Pestle', null, 120.00, 'Crafted from volcanic stone, this authentic molcajete is a timeless kitchen tool used in Mexican cooking for centuries. Ideal for grinding spices, making salsas, guacamole, and other traditional dishes, it brings out deep, rich flavors that you just can’t get with a blender. Hand-carved with three sturdy legs and a rough texture perfect for crushing ingredients, this molcajete is both functional and a beautiful cultural piece for your kitchen.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_b23f4783-b2aa-4a37-b72b-31f341216873.png?v=1750938781', 50, 'My Store', false, false),
  ('CMX-TRADITIONAL-CHARRO-SOMBRERO', 'Traditional Mexican Charro Sombrero', null, 150.00, 'Make a bold statement with this authentic Mexican Charro Sombrero. Handcrafted with luxurious green velvet and intricate silver embroidery, this iconic hat celebrates the rich culture and artistry of Mexico. Perfect for festive occasions, cultural displays, or as a standout decorative piece, it blends tradition with striking style. Made in Mexico Embroidered silver detailing with metallic accents Structured wide brim with classic upturned edges Ideal for celebrations, costumes, or decor', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_34ad63b2-9df7-4dfc-9227-1a78f13f4104.png?v=1750936614', 50, 'My Store', false, false),
  ('CMX-HANDWOVEN-PALM-BASKET-WITH-LID', 'Handwoven Mexican Palm Basket with Lid', null, 80.00, 'Bring a touch of Mexican tradition into your home with this beautifully handwoven palm basket. Crafted by skilled artisans, it features vibrant, colorful detailing and a secure lid adorned with handmade flowers, perfect for holding small items, gifting, or simply as a decorative piece. Each basket is unique, showcasing the charm and character of authentic Mexican craftsmanship. Handmade in Mexico Ideal for gifts, jewelry, keys, or home decor', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_8f2de186-f3e2-4055-a4ed-1f3e9c5ed632.png?v=1750936395', 50, 'My Store', false, false),
  ('CMX-TAMARIND-CONCENTRATE-EL-YUCATECO', 'Tamarind Concentrate, El Yucateco', 'beverages', 38.00, '🍬 Sweet, tangy, and unmistakably Mexican Enjoy the authentic flavor of Tamarind , a beloved Mexican classic made from real tamarind pulp. This concentrate is bold, fruity, and just the right amount of tart — perfect over ice or paired with your favorite snacks. 🌿 Makes up to 4 liters 🌞 Refreshing tropical flavor 🍹 Ideal for aguas frescas or mocktails. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_cf8e42dd-aa98-466c-bfaf-ef8fe0afc947.png?v=1750935728', 50, 'My Store', false, false),
  ('CMX-HORCHATA-CONCENTRATE-EL-YUCATECO', 'Horchata Concentrate, El Yucateco', 'beverages', 17.00, '🥛 Creamy, sweet, and full of nostalgia A beloved Mexican classic, this Horchata de Arroz concentrate captures the comforting taste of cinnamon-infused rice milk. Just mix with water and ice for a refreshing, milky beverage that’s perfect with any meal or as a sweet treat on its own. 🧋 Makes up to 4 liters 🌾 Creamy rice flavor with a hint of cinnamon ❄️ Best served cold 🇲🇽 A traditional favorite for generations. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_b603a7cf-addf-4425-b9af-b6a46add2b13.png?v=1750935540', 50, 'My Store', false, false),
  ('CMX-JAMAICA-DRINK-CONCENTRATE-EL-YUCATECO', 'Jamaica Drink Concentrate, El Yucateco', 'beverages', 19.00, '🌺 Traditional Sabor Mexicano This bold and refreshing Jamaica (hibiscus flower) drink concentrate, brings a taste of Mexican tradition straight to your glass. Just mix with cold water and ice to enjoy a naturally tangy, floral-flavored agua fresca — a staple in every Mexican household. 🧃 Makes up to 4 liters 🥤 Rich hibiscus flavor ❄️ Serve cold over ice 🇲🇽 Perfect for meals, fiestas, or a refreshing break. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_ad72d5b1-06c8-4a0c-b678-7577ed302f14.png?v=1750935152', 50, 'My Store', false, false),
  ('CMX-QUESO-COTIJA-EXCELSIOR-AGED-CHEESE', 'Queso Cotija Excelsior, Mexican Aged Cheese', 'masa', 45.00, 'Queso Cotija Excelsior is a traditional Mexican aged cheese, known for its bold, salty flavor and firm, crumbly texture . Perfect as a finishing touch, this cheese doesn’t melt, making it ideal for sprinkling over tacos, elotes, enchiladas, salads, and more. 🧀 Aged to perfection 🌽 Made with cow''s milk 🇲🇽 Authentic Mexican flavor 💡 Similar to Parmesan but with a sharper bite A staple in Mexican cuisine, bring depth and tradition to every dish. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_b6d7d2b3-ae35-43f8-8d1e-7539109df8dd.png?v=1750748388', 50, 'My Store', false, false),
  ('CMX-CACTUS-GUAJILLO-454G', 'Cactus Guajillo 454g', 'masa', 9.00, 'A rich blend of traditional flavors, Nopalitos en Salsa de Chile Guajillo from Nopal Foods bring the authentic taste of Mexico to your table. Tender cactus strips (nopalitos) are cooked in a deliciously smoky and mildly spicy guajillo chile sauce. 🌿 Plant-based &amp; nutritious 🌶️ Made with real guajillo chiles 🍅 Great with tacos, tostadas, or as a side 🥫 Net weight: 454g. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_1e5a184e-3f0b-49d4-8531-856b21243d55.png?v=1750700705', 50, 'My Store', false, false),
  ('CMX-LA-COSTENA-JALAPENO-SLICES', 'La Costeña, Jalapeño Slices', 'masa', 9.00, 'Add bold Mexican flavor to any dish with La Costeña Jalapeño Rajas , crisp strips of green jalapeños pickled to perfection in vinegar, carrots, and onions. 🫑 Tangy, spicy &amp; authentic 🫑 Ready-to-use topping for tacos, tortas, nachos &amp; more 🫑 No preservatives added 🫑 Net weight: 220g (Drained: 121g). Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_65a61c1b-7564-483b-a767-ecd29fe8db86.png?v=1750700137', 50, 'My Store', false, false),
  ('CMX-DRIED-CORN-HUSKS', 'Dried Corn Husks', 'masa', 33.50, 'Wrap your tamales in tradition with our natural dried corn husks , carefully selected and sun-dried for the perfect hold and steam. 🌽 100% natural and food-safe 🌽 Ideal for tamales. 🌽 Soak in warm water before use for flexibility 🌽 Cleaned and bundled for convenience 🌽 Net weight: approx. 500g bundle. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_8337b479-4f6f-419d-85d6-e4b17fa1555b.png?v=1750699617', 50, 'My Store', false, false),
  ('CMX-ORGANIC-BLUE-AGAVE-SYRUP-MAYAMEL-510G', 'Organic Blue Agave Syrup, Mayamel 510g', 'masa', 39.00, 'Sweeten naturally with Mayamel Jarabe de Agave Azul , a premium syrup made from 100% organic blue agave. 🌱 Organic and pure – sourced from blue agave plants in Mexico 🌱 Low glycemic index – a healthier alternative to sugar and honey 🌱 Perfect for coffee, tea, smoothies, pancakes, and baking 🌱 Rich amber color and a smooth, delicate flavor 🌱 Packaged in a compact 510g bottle – ideal for home or on-the-go use. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_e38aa1cc-e559-4523-97d6-8376ba2aff64.png?v=1750699418', 50, 'My Store', false, false),
  ('CMX-BLUE-CORN-FLOUR-NATURELO', 'Blue Corn Flour, Naturelo', 'masa', 580.00, 'Naturelo reinvents corn flour with a commitment to sustainability and quality, proudly made in Mexico. 🌽 Environmentally friendly – designed with the planet in mind 🌽 High-performance corn flour for tortillas, tamales, and masa-based recipes 🌽 Packaged in eco-conscious materials 🌽 Produced by a brand that values innovation and responsibility 🌽 Ideal for both industrial kitchens and artisan producers. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_046d6c1b-fe39-4b68-b0f1-f338ddebe0ac.png?v=1750699134', 50, 'My Store', false, false),
  ('CMX-NIXTAMALIZED-CORN-FLOUR-OMALLI-20KG', 'Nixtamalized Corn Flour, Omalli 20kg', 'masa', 500.00, 'Omalli delivers premium nixtamalized corn flour made from select maize, fortified with essential nutrients to support both health and tradition. 🌽 20kg bulk packaging – ideal for restaurants, taquerías, and large-scale use 🌽 Fortified with folic acid, iron, zinc, and B vitamins (B1, B2, B3) 🌽 Perfect for preparing authentic tortillas, tamales, and masa-based dishes 🌽 Made from nixtamalized maize for richer flavor and better texture 🌽 Naturally gluten-free. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_e6f669b6-ce5f-45e7-9b6a-e915c2d687c7.png?v=1750692404', 50, 'My Store', false, false),
  ('CMX-MASECA-NIXTAMALIZED-CORN-FLOUR', 'Maseca, Nixtamalized Corn Flour', 'masa', 25.50, 'Bring the heart of Mexican cuisine to your kitchen with Maseca , the leading nixtamalized corn flour made from 100% selected corn. 🌽 Ideal for tortillas, tamales, gorditas, and more 🌽 Naturally gluten-free 🌽 Enriched with folic acid, iron, zinc, and vitamins B1, B2, B3 🌽 Made from whole, selected corn kernels 🌽 1kg of authentic masa harina for all your homemade cravings Traditional taste. Versatile. Nutrient-rich. Your go-to base for real Mexican flavor. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_d822254c-db0d-43e4-bd14-b7f88992723d.png?v=1750691083', 50, 'My Store', false, false),
  ('CMX-DEHYDRATED-CACTUS', 'Dehydrated Cactus', 'masa', 25.00, 'Boost your daily wellness with Nopal Tenochtitlan , a 100% natural dehydrated nopal (cactus) fiber rich in nutrients and completely free from added sugars or preservatives. 🌿 Pure cactus fiber – from dehydrated nopal 🌿 0% added sugars or preservatives 🌿 High in fiber – supports digestion and gut health 🌿 Great for smoothies, juices, or as a daily supplement 🌿 400g resealable pouch for freshness and ease A superfood rooted in Mexican tradition, now modernized for your healthy lifestyle. Clean. Green. Natural. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_29dcfbc0-5ef9-46b5-af82-591349bd4308.png?v=1750688626', 50, 'My Store', false, false),
  ('CMX-WHOLE-BLACK-BEANS-LA-SIERRA', 'Whole Black Beans. La Sierra', 'masa', 38.00, 'A staple in Mexican kitchens, La Sierra brings you perfectly cooked whole black beans (frijoles negros enteros) ready to heat and enjoy. Whether as a side, in soups, or part of your favorite burrito, these beans are rich in flavor and nutrition. 🫘 Traditional whole black beans 🍽️ Ideal for tacos, soups, rice dishes &amp; more 🥄 Ready-to-eat – no soaking or cooking required 📦 Large 3kg can – great for families or food service 🇲🇽 Product of Mexico. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_4f4db770-6dc0-43a3-b0ea-b1479ed56703.png?v=1750687848', 50, 'My Store', false, false),
  ('CMX-WHITE-HOMINY-IN-BRINE-EL-MEXICANO-MAIZ-POZOLERO', 'White Hominy in Brine, El Mexicano (Maiz Pozolero)', 'masa', 40.00, 'A pantry essential for traditional Mexican cuisine. El Mexicano’s White Hominy (Maíz Blanco) is prepared and ready to use in hearty dishes like pozole, menudo, or tamales. Each kernel is soaked, softened, and packed in brine to preserve its signature flavor and texture. 🌽 Authentic Mexican-style white hominy 🍲 Ideal for pozole, stews, and soups 🥫 Large 3.01kg tin – perfect for families or catering 💧 Ready-to-use – just rinse and cook. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_9af8080d-af61-41eb-896b-53915267f1c1.png?v=1750687577', 50, 'My Store', false, false),
  ('CMX-ACHIOTE-PASTE-LA-MERIDANA', 'Achiote Paste. La Meridana', 'masa', 10.50, 'Achiote is the heart of Yucatán flavor, earthy, peppery, and beautifully red. La Meridana’s achiote paste is made with annatto seeds, spices, and herbs, perfect for creating cochinita pibil, grilled meats, or rich marinades that taste like home. 🌶️ Authentic Yucatán-style seasoning 🌿 Made with annatto, garlic, and spices 🔥 Ideal for marinades, tacos al pastor, and grilling 💛 Vibrant color and bold flavor in every spoonful.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_665d9e52-38b2-4c55-ad17-fd53877928de.png?v=1750686660', 50, 'My Store', false, false),
  ('CMX-WHITE-HOMINY-IN-BRINE-EL-MEXICANO-822G-MAIZ-POZOLERO', 'White Hominy in Brine, El Mexicano 822g (Maiz Pozolero)', 'masa', 18.50, 'An essential in every traditional Mexican kitchen. These soft, puffy kernels of white hominy are pre-cooked and packed in brine, ready to bring rich texture and authentic flavor to your pozole, soups, and stews. 🌽 Made from 100% nixtamalized white corn 🍲 Perfect for pozole and hearty Mexican soups ✅ No soaking or boiling needed – just heat and serve 🧂 Packed in brine to preserve taste and freshness 🇲🇽 Authentic flavor straight from Mexico to your plate. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_0ddf533e-6b60-4386-85ef-88d65075a421.png?v=1750686334', 50, 'My Store', false, false),
  ('CMX-MAIZENA-CORN-STARCH', 'Maizena Corn Starch', 'masa', 17.00, 'The original and trusted kitchen essential in every Mexican household. Maizena’s corn starch is your secret ingredient for creating dishes that are crispier, fluffier, and creamier, from fried favorites to velvety soups and baked treats. 🌽 Made with natural corn 🥞 Perfect for fluffy pancakes &amp; soft cakes 🍗 Adds crispness to fried foods 🥣 Thickens sauces, soups &amp; desserts effortlessly 👩🍳 A versatile pantry staple for sweet or savory recipes. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_8bb77fd8-59ba-4c26-aec1-5415703ca5c5.png?v=1750684622', 50, 'My Store', false, false),
  ('CMX-CHOCOLATE-ABUELITA', 'Chocolate Abuelita', 'masa', 52.50, 'Warm, nostalgic, and full of flavor, Abuelita is the taste of Mexican tradition in every cup. These classic chocolate tablets are infused with cinnamon and spices, creating a rich, frothy drink when melted into hot milk. Whether it’s for chilly mornings or festive evenings, Abuelita brings comfort straight from la cocina. As sweet as grandma''s hug! 🍫 Authentic Mexican-style hot chocolate ☕ Just melt into milk and whisk until frothy 🌶️ Subtle hints of cinnamon and spice 👵🏼 A beloved recipe passed down for generations 📦 6 tablets per pack – makes 6 full liters. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_564339b9-314c-4f12-9f3c-59def05155c3.png?v=1750684259', 50, 'My Store', false, false),
  ('CMX-GOAT-MILK-CARAMEL-CAJETA-QUEMADA-CORONADO', 'Goat Milk Caramel (Cajeta Quemada), Coronado', 'masa', 30.50, 'Rich, velvety, and unmistakably Mexican, Coronado''s Cajeta Quemada is a traditional caramel thick sauce made from goat’s milk, slow-cooked to achieve its deep, toasty flavor. A sweet staple in Mexican households, it''s perfect for drizzling over pancakes, fruit, ice cream, or even spooned straight from the bottle. 🍮 Made with 100% goat''s milk 🔥 Classic “quemada” (burnt) style for a deeper caramelized taste 🥞 Ideal for desserts, pastries, or breakfast toppings 🇲🇽 Crafted with care in Mexico 📦 660g squeeze bottle – mess-free &amp; easy to use. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_ed6e7d04-b500-41b5-93d4-378e7290d23d.png?v=1750683882', 50, 'My Store', false, false),
  ('CMX-CACTUS-IN-BRINE-450G', 'Cactus in Brine 450g', 'masa', 9.00, 'Tender cactus strips preserved in a fragrant brine, perfect for adding a fresh and authentic Mexican touch to your meals. These nopales are subtly seasoned to enhance their natural flavor, ideal for salads, tacos, or as a zesty side dish. 🍃 Nopales (cactus) in aromatic brine 🥒 Naturally rich in fiber and antioxidants 🌿 Preserved with herbs for enhanced flavor 🌮 Ready to serve with salads, tacos, or eggs 📦 450g jar, vegan &amp; gluten-free. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_fb7dfed1-744d-4e68-8f16-a6e9e257f825.png?v=1750683591', 50, 'My Store', false, false),
  ('CMX-PICKLE-CACTUS-NOPALES-EN-ESCABECHE-NOPAL-FOODS', 'Pickle Cactus (Nopales en Escabeche), Nopal Foods', 'masa', 10.00, 'Bring home the goodness of Mexico with tender, sliced nopales (cactus) preserved in brine. A low-calorie, high-fiber staple that’s rich in antioxidants and perfect for tacos, salads, eggs, or even smoothies. 🌵 Traditional Mexican cactus slices 🥗 Great in salads, tacos, and stews 💧 Packed in brine for freshness 🌿 Naturally low in fat &amp; high in fiber 📦 450g jar – ready to serve. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_ce5d5c58-bd3c-45a6-9668-a4f5f34cc582.png?v=1750683134', 50, 'My Store', false, false),
  ('CMX-WHOLE-BAYO-BEANS-LA-COSTENA', 'Whole Bayo Beans, La Costena', 'masa', 14.50, 'Wholesome, earthy, and deliciously smooth, these Whole bayo beans (light brown beans) are a Mexican kitchen classic. They are perfect for tostadas, tacos, or as a side dish. 🌿 Made from authentic bayo beans 🥣 Great for traditional plates, bowls, or dips 📦 560g Net Weight in Can Container – pantry-friendly and travel-ready. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_bad9a7df-3a4b-41c6-8063-4948c64cca89.png?v=1750681491', 50, 'My Store', false, false),
  ('CMX-REFRIED-BAYO-BEANS-LA-COSTENA', 'Refried Bayo Beans, La  Costeña', 'masa', 14.50, 'Wholesome, earthy, and deliciously smooth, these refried bayo beans (light brown beans) are a Mexican kitchen classic. Packaged in a convenient pouch for quick heating, they are perfect for tostadas, tacos, or as a side dish. 🌮 Mild and creamy flavor 🌿 Made from authentic bayo beans 🔥 Heat-and-serve pouch – no mess, no fuss 🥣 Great for traditional plates, bowls, or dips 📦 430g pouch – pantry-friendly and travel-read. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_732b1194-a86b-4701-974e-ec32281f50e9.png?v=1750681219', 50, 'My Store', false, false),
  ('CMX-REFRIED-BLACK-BEANS-LA-COSTENA', 'Refried Black Beans, La Costena', 'masa', 15.50, 'Creamy, savory, and ready to heat, these refried black beans are the heart of countless Mexican dishes. Whether you’re spreading them in a burrito, spooning them next to rice, or scooping them with chips, they bring rich, authentic flavor every time. 🫘 Traditional Mexican flavor, ready in minutes 🫘 Smooth, velvety texture 🫘 Perfect for tacos, tostadas, bowls &amp; sides 🫘 580g tin – pantry staple for easy meals. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_ee1de4d3-7239-48d1-8794-6d326174e3bb.png?v=1750518308', 50, 'My Store', false, false),
  ('CMX-HUITLACOCHE-LA-COSTENA', 'Huitlacoche, La Costeña', 'masa', 35.00, 'Earthy, bold, and rich in umami, Huitlacoche (Mexican truffle) is a delicacy straight from the cornfields of Mexico. Packed with flavor and tradition, this smoky, mushroom-like ingredient adds a gourmet twist to quesadillas, tacos, and soups. 🍄 Authentic Mexican delicacy 🍄 Smoky, earthy, and slightly sweet 🍄 Ready to use – no prep needed 🍄 380g – ideal for specialty dishes or creative cooking. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_e12d705c-ca19-403c-9d54-12c7db91a3ed.png?v=1750517904', 50, 'My Store', false, false),
  ('CMX-CHIPOTLE-SAUCE-220ML-LA-COSTENA', 'Chipotle Sauce 220ml, La Costeña', 'masa', 10.50, 'Bold, smoky, and made to impress. La Costeña’s Salsa de Chipotle blends rich chipotle peppers with tomato and onion for a full-bodied flavor that transforms tacos, grilled meats, and even sandwiches. 🔥 Authentic chipotle-tomato blend 🔥 Medium heat with deep smoky flavor 🔥 Ready to pour straight from the can 🔥 220g – ideal for meals, marinades, and dips. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_0cce6d21-77d2-4084-9c81-5408d9da8b44.png?v=1750517587', 50, 'My Store', false, false),
  ('CMX-DICED-CHIPOTLE-PEPPERS-LA-COSTENA', 'Diced Chipotle Peppers, La  Costeña', 'masa', 19.00, 'Smoky, spicy, and deeply rich, La Costeña’s diced chipotle peppers bring that unmistakable heat and depth to any dish. Just a spoonful adds bold flavor to tacos, stews, sauces, and marinades. 🌶️ Authentic smoked chipotle flavor 🌶️ Pre-diced for easy use in recipes 🌶️ Perfect for marinades, tacos, and slow-cooked dishes 🌶️ 230g jar – compact size, big flavor impact. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_f91adb42-a427-410c-907d-c537d964a4ed.png?v=1750517260', 50, 'My Store', false, false),
  ('CMX-JALAPENO-NACHOS-PICKLED-LA-COSTENA', 'Jalapeño Nachos Pickled, La Costeña', 'masa', 15.00, 'Add some heat to your plate with La Costeña’s signature nacho-sliced jalapeños. Crunchy, tangy, and fiery enough to kick your tacos, burgers, and quesadillas up a notch. 🌶️ Crisp jalapeño slices pickled to perfection 🌶️ Ready to serve, perfect for nachos, tacos &amp; more 🌶️ Balanced heat with bold Mexican flavor 🌶️ 440g jar, pantry must-have for spice lovers. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_debf776b-7a4d-4da4-9c64-66292fc0644d.png?v=1750516808', 50, 'My Store', false, false),
  ('CMX-BLUE-CORN-MASA-FLOUR-NATURELO', 'Blue Corn Masa Flour, Naturelo', 'masa', 23.80, 'Reinvent your tortillas with the bold, earthy flavor of blue corn. Naturelo’s nixtamalized masa flour is gluten-free, GMO-free, and perfect for making authentic Mexican tortillas, tamales, and more, straight from your kitchen. 🌽 Made from 100% non-GMO blue corn 🌽 Naturally gluten-free &amp; vegan 🌽 Rich, nutty taste and striking color 🌽 Ideal for tortillas, tamales, sopes &amp; more 🌽 1kg bag – resealable and pantry-friendly. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_51a7b599-1295-4ed7-bd7d-1c71b3a5e707.png?v=1750516246', 50, 'My Store', false, false),
  ('CMX-AGAVE-SYRUP-ORGANIC', 'Agave Syrup Organic', 'masa', 18.00, 'Sweeten things up, naturally. B Sweet’s Organic Agave Syrup is your go-to vegan-friendly sweetener, made from pure agave and 30% sweeter than sugar with a lower glycemic index. Great for coffee, smoothies, baking, or drizzling over pancakes! 🍯 USDA Organic Certified 🍯 100% plant-based &amp; vegan 🍯 30% sweeter than sugar – use less, enjoy more 🍯 No added sugars or preservatives 🍯 400g bottle – easy to pour and store. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_ec05ae2b-ae22-4c14-aba8-b8fdfd09e301.png?v=1750515924', 50, 'My Store', false, false),
  ('CMX-MOLE-PASTE-AZTECA', 'Mole Paste, Azteca', 'masa', 50.25, 'Rich, bold, and deeply traditional. Mole Azteca delivers the full-bodied flavor of authentic Mexican mole in a convenient, foodservice-sized pack, perfect for professional kitchens or mole lovers who just can’t get enough. 🌶️ Classic mole flavor with a smooth, velvety texture 🌶️ Ideal for chicken, enchiladas, and rice dishes 🌶️ Made with a blend of chiles, nuts, spices, and chocolate 🌶️ 1kg pouch – restaurant-ready or great for big batch meals. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_3065fb79-57d9-4fc1-85ad-34c8aa7035db.png?v=1750515662', 50, 'My Store', false, false),
  ('CMX-MOLE-PASTE-DONA-MARIA', 'Mole Paste, Doña María', 'masa', 25.70, 'Traditional mole, straight from the source. Doña María’s mole paste delivers bold, complex flavor in a concentrated form, just add broth and simmer into the rich, chocolatey sauce every Mexican kitchen swears by. 🌶️ Classic mole recipe with a deep, layered taste 🌶️ Just dilute, stir, and serve over meats or enchiladas 🌶️ Rich in chiles, chocolate, nuts, and spice 🌶️ 235g jar – makes up to 8 generous portions. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_6267457e-0757-4d05-baea-e5dca999e0a7.png?v=1750515534', 50, 'My Store', false, false),
  ('CMX-MOLE-READY-TO-SERVE-DONA-MARIA', 'Mole, Ready to Serve, Doña María', 'masa', 19.00, 'A Mexican classic made easy. Doña María’s ready-to-serve mole blends rich chocolate, chili, and spice into a velvety sauce that instantly elevates your chicken, enchiladas, or rice dishes — no prep needed. 🍫 Blend of chocolate, chili, nuts, and spices 🍫 Just heat and serve – perfect for busy kitchens 🍫 360g pack – ideal for 3–4 servings. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_2d051624-6028-4aee-b4ad-109d5276837b.png?v=1750515165', 50, 'My Store', false, false),
  ('CMX-FLOUR-TORTILLA-500G', 'Flour Tortilla 500g', 'bulk', 21.00, 'Soft, flexible, and melt-in-your-mouth delicious, made from the finest ingredients, Intermex Flour Tortillas bring authentic Mexican flavor to everything from breakfast burritos to late-night quesadillas. Heat them for seconds, fill them with your favorite ingredients, and enjoy the unmistakable taste of fresh-made tortillas at home. 🌾 Crafted with premium wheat flour for ultra-soft texture 🌾 Resealable 500 g pouch to lock in freshness 🌾 Versatile, great for tacos, burritos, quesadillas &amp; wraps 🌾 Ready to heat and serve in under 30 seconds. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_08f0cc3b-3952-42a0-8969-81ef87c54cb5.png?v=1750513818', 50, 'My Store', false, false),
  ('CMX-CHICKEN-CHORIZO', 'Mexican Chicken Chorizo, Intermex', 'bulk', 29.00, 'Lighter in meat, bold in flavor. Intermex’s Mexican Chicken Chorizo delivers the same rich, spicy goodness you love with a leaner twist. Perfect for those who want to keep it lighter without sacrificing that authentic kick. 🌶️ Made with premium seasoned chicken 🌶️ Lower fat, same bold flavor 🌶️ Infused with traditional Mexican spices 🌶️ Great for tacos, rice bowls, or breakfast scrambles 🌶️ Easy to cook – available fresh or frozen. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_48990b3d-1ce7-4de6-a619-4555d0fc1e3c.png?v=1750513539', 50, 'My Store', false, false),
  ('50', 'Mexican Beef Chorizo, Intermex', 'bulk', 25.00, 'Bring bold, smoky heat to your dishes with Intermex’s traditional Mexican Beef Chorizo. Made with premium beef and a punchy blend of spices, this sausage is perfect for tacos, breakfast scrambles, or grilling into juicy perfection. 🌶️ Authentic Mexican-style chorizo 🌶️ Made with high-quality seasoned beef 🌶️ Rich, spicy flavor with a smoky kick 🌶️ Ideal for tacos, burritos, eggs, or grilling 🌶️ Available fresh or frozen – easy to cook and versatile in use. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_14ddee88-7177-4a27-b8eb-cbcabadf4e3c.png?v=1750513214', 50, 'My Store', false, false),
  ('CMX-TORTILLA-CHIPS', 'Tortilla chips', 'bulk', 27.00, 'Crispy, golden, and made to be dipped! Intermex Classic Tortilla Chips are crafted from stone-ground corn for that authentic crunch and taste. Whether you''re scooping guac, layering nachos, or snacking straight from the bowl, these chips deliver a bold bite every time. 🌽 Made from 100% stone-ground corn 🌽 Perfectly crispy for dipping, topping, or snacking solo 🌽 No added preservatives or artificial flavors 🌽 Bold taste, traditional texture 🌽 Ideal for parties, picnics, or everyday cravings. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_df69f3bb-3de7-4201-95f1-fe01f1174417.png?v=1750512980', 50, 'My Store', false, false),
  ('CMX-GOLDEN-TOSTADAS-10', 'Golden Tostadas 10 pieces, Intermex', 'bulk', 17.00, 'Intermex Golden Tostadas are lightly toasted corn discs made the authentic Mexican way, golden, crispy, and made to be topped. Ideal for layering with beans, meats, veggies, or enjoying straight from the bag. 🌽 Made from 100% corn, authentic and gluten-free 🌽 Perfectly crisp for layering or dipping 🌽 No preservatives or additives 🌽 Ready-to-use and restaurant-quality 🌽 200g pack – crafted for sharing or storing. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_fb67a977-544b-4c92-aa87-bfb38976cb9c.png?v=1750512432', 50, 'My Store', false, false),
  ('CMX-TOSTADAS-WITH-SESAME-SEEDS-10', 'Tostadas with sesame seeds, Intermex (10 pieces)', 'bulk', 17.00, 'Crispy, bold, and ready to top! Intermex Tostadas are made from stone-ground corn and baked to a perfect crunch, the ideal base for your favorite Mexican flavors. 🌽 Made with authentic stone-ground corn 🌽 Crunchy and sturdy, perfect for piling on toppings 🌽 Lightly toasted with a bold, nutty flavor 🌽 Great for tostadas, ceviche, or snack platters 🌽 250g pack – resealable and ready to serve anytime. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_c9617a7a-9c51-4586-a653-20cd61fa4bb7.png?v=1750510954', 50, 'My Store', false, false),
  ('CMX-CORN-TORTILLA-6INCH-500GM', 'Corn Tortilla 6inch, Intermex 500gm', 'bulk', 20.00, 'Made with tradition in every fold, Intermex Corn Tortillas are crafted from authentic Mexican masa for the perfect texture and taste. Soft, versatile, and full of heritage, they''re the foundation of every great taco night. 🌽 Made from traditional corn masa 🌽 Soft, pliable, and easy to heat 🌽 Ideal for tacos, enchiladas, tostadas &amp; more 🌽 500 pack – perfect for family meals or food service 🌽 Crafted by Intermex, authentic Mexican flavor in every bite. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/2_0455f02c-8a8e-4676-9787-8ad60cabf280.png?v=1750510751', 50, 'My Store', false, false),
  ('CMX-NO-GUILT-CHURRITOS-INZI', 'No Guilt Churritos, Inzi', 'bulk', 22.00, 'Crunch with a kick. Inzi’s No Guilt Churritos bring the zing of chili and lime in every bite — bold in flavor, clean in ingredients, and made to keep you going without the guilt. 🍋 High in protein, 30g per pack 🍋 Packed with fiber, 15g per pack 🍋 Keto &amp; vegan friendly 🍋 Zesty chili-lime flavor 🍋 65g resealable bag, your go-to snack with a twist. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/WhatsAppImage2025-10-08at12.26.54PM.jpg?v=1759914967', 50, 'My Store', false, false),
  ('CMX-NO-GUILT-NACHOS-INZI', 'No Guilt Nachos,Inzi', 'bulk', 18.00, 'Snack clean, crunch loud. Inzi''s No Guilt Nachos are the perfect balance of bold flavor and better-for-you ingredients, high in protein, rich in fiber, and totally free from the guilt. 🌽 High in protein, 30g per pack 🌽 High in fiber, 15g per pack 🌽 Keto &amp; vegan friendly 🌽 Preservative-free 🌽 Contains prebiotics 🌽 50g resealable bag for guilt-free snacking anytime. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/WhatsAppImage2025-10-31at10.36.47AM.jpg?v=1761898331', 50, 'My Store', false, false),
  ('CMX-CHAMOY-SAUCE-EL-CHILERITO-1LT', 'Chamoy Sauce, El Chilerito 1lt', 'salsas', 33.50, 'Sweet, sour, spicy, the holy trinity of Mexican flavor in a bottle. El Chilerito Salsa Chamoy is a bold and tangy chamoy sauce perfect for drizzling on fruit, snacks, and even cocktails. It’s the ultimate party essential! 🌶️ Brand: El Chilerito 🌶️ Sweet, tangy, and mildly spicy 🌶️ Classic chamoy made for fruit, chips, and drinks 🌶️ Loved for micheladas, mangonadas, and candy dips 🌶️ 1L bottle – perfect for sharing or stocking up. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_26b2d769-6dcc-4141-8b94-77ef16acaa99.png?v=1750338490', 50, 'My Store', false, false),
  ('CMX-GUACAMOLE-SALSA-LA-COSTENA', 'Guacamole Salsa, La Costeña', 'salsas', 0.00, 'Creamy, zesty, and ready to pour — La Costeña Guacamole Salsa brings together the rich texture of avocado with a mild spice for a perfect finishing touch to tacos, nachos, burgers, or grilled veggies. No chopping, no mashing — just open and enjoy! 🌶️ Brand: La Costeña 🌶️ Smooth avocado-based salsa 🌶️ Mild heat with fresh lime and onion flavor 🌶️ Perfect for tacos, nachos, salads, or dipping 🌶️ 445 g bottle – easy to pour and serve. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_90bae10e-f297-46ea-81a6-365684d80613.png?v=1750338212', 50, 'My Store', false, false),
  ('CMX-HOMESTYLE-SAUCE-LA-COSTENA', 'Homestyle Sauce, La Costeña', 'salsas', 5.00, 'A classic, fire-roasted flavor straight from the Mexican kitchen. La Costeña Salsa Casera Mexicana (Tatemada) is made with roasted tomatoes, onions, and chilies to give you that authentic, homemade taste. A must-have for tacos, eggs, or grilled meats. 🌶️ Brand: La Costeña 🌶️ Roasted tomato-based Mexican-style salsa 🌶️ Medium heat with a smoky, homemade flavor 🌶️ Ideal for topping tacos, eggs, grilled chicken or steak 🌶️ 250 g bottle – rich, thick texture. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_05539e60-792c-45e3-93eb-f20f68c403e7.png?v=1750337897', 50, 'My Store', false, false),
  ('CMX-GUACAMOLE-SAUCE-250GM-LA-COSTENA', 'Guacamole Sauce 250gm, La Costeña', 'salsas', 19.50, 'Creamy, zesty, and perfectly spiced! La Costeña Salsa de Guacamole brings the smooth taste of avocado with a tangy kick of green chili — all in one pourable sauce. Drizzle it on tacos, nachos, or grilled veggies for instant flavor. 🌶️ Brand: La Costeña 🌶️ Avocado-based creamy green sauce 🌶️ Tangy, mildly spicy guacamole flavor 🌶️ Perfect for tacos, nachos, salads, and more 🌶️ 250 g bottle – smooth, pourable consistency. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_eea26e81-3a9f-4eb6-9a0d-6d78b581899c.png?v=1750337531', 50, 'My Store', false, false),
  ('CMX-GREEN-SAUCE-250G-LA-COSTENA', 'Green Sauce 250g, La Costeña', 'salsas', 4.00, 'Zesty, bright, and full of flavor. La Costeña Salsa Verde is made with fresh tomatillos and green chiles for a tangy punch with just the right amount of heat. It’s a must-have for tacos, eggs, enchiladas, and everything in between. 🌶️ Brand: La Costeña 🌶️ Made with tomatillos &amp; green chiles 🌶️ Tangy, mildly spicy flavor 🌶️ Ideal for tacos, grilled meats, and breakfast dishes 🌶️ 250 g glass bottle – traditional salsa texture. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/lacostenagreen.jpg?v=1767352307', 50, 'My Store', false, false),
  ('CMX-HOT-SAUCE-LA-COSTENA', 'Hot Sauce, La Costeña', 'salsas', 3.00, 'Classic Mexican heat in a handy bottle. La Costeña Salsa Picante blends ripe red chiles, tomatoes, and spices into a smooth, fiery sauce that perks up tacos, grilled meats, soups—or anything that needs a quick kick. 🌶️ Brand: La Costeña 🌶️ Smooth, pourable consistency 🌶️ Medium-hot chile flavor with tangy tomato notes 🌶️ Great for marinades, eggs, tacos, and snacks 🌶️ 140 ml glass bottle – perfect table-top size. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_7675837c-ffe0-45eb-8e5d-d4b1d07c07c6.png?v=1750336868', 50, 'My Store', false, false),
  ('CMX-DIP-SAUCE-MEDIUM-LA-COSTENA', 'Dip Sauce Medium, LA Costeña', 'salsas', 17.50, 'A smooth balance of flavor and spice, La Costeña Salsa Dip Medium offers a rich tomato base blended with mild chilies and onions for that perfect, family-friendly dip. Great with chips, tacos, or as a party favorite. 🌶️ Brand: La Costeña 🌶️ Mild-to-medium spice level for all palates 🌶️ Made with tomatoes, green peppers &amp; onion 🌶️ Smooth and scoopable texture 🌶️ 453 g jar. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_93d85132-418e-481e-b140-75d67da0345d.png?v=1750336550', 50, 'My Store', false, false),
  ('CMX-DIP-HOT-SAUCE-LA-COSTENA', 'Dip Hot Sauce, La Costeña', 'salsas', 17.50, 'Turn up the heat on snack time! La Costeña Salsa Dip Hot blends bold tomatoes, green peppers, and just the right spice for a chunky, fiery dip perfect for chips, nachos, or even drizzling over tacos. 🌶️ Brand: La Costeña 🌶️ Chunky texture with a hot, flavorful kick 🌶️ Perfect for dipping, topping, or cooking 🌶️ Made with real tomatoes, chilies, and spices 🌶️ 453 g jar. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_255bf4b6-0eed-463a-a0dc-651b4abe67ca.png?v=1750336159', 50, 'My Store', false, false),
  ('CMX-GREEN-SAUCE-HABANERO-LA-COSTENA', 'Green Sauce Habanero, La Costeña', 'salsas', 3.00, 'Zesty, fresh, and packing a punch, La Costeña Salsa de Habanero Verde brings green habanero fire to your meals with a bright and tangy twist. A go-to for taco nights, grilled meats, and savory breakfasts. 🌶️ Brand: La Costeña 🌶️ Made with green habanero chiles 🌶️ Tangy and bold with a vibrant heat 🌶️ Ideal for eggs, tacos, meats &amp; more 🌶️ 145 ml glass bottle. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_809efe8e-3b62-49cd-a950-3a69dfc760c5.png?v=1750329636', 50, 'My Store', false, false),
  ('CMX-RED-HABANERO-SAUCE', 'Red Habanero Sauce', 'salsas', 3.00, 'Turn up the heat! La Costeña Salsa de Habanero Rojo delivers a fiery burst of red habanero flavor that spice lovers crave. With bold notes and just the right kick, it’s the perfect match for meats, tacos, and even soups. 🌶️ Brand: La Costeña 🌶️ Made with red habanero chiles 🌶️ Extra hot with full-bodied chile flavor 🌶️ Perfect for tacos, meats, soups, and marinades 🌶️ 145 ml glass bottle. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_e9f344e1-af9e-42f1-9bee-68df6c718e35.png?v=1750329285', 50, 'My Store', false, false),
  ('CMX-CHIPOTLE-SAUCE-LA-COSTENA', 'Chipotle Sauce,La Costeña', 'salsas', 7.60, 'Smoky, rich, and full of flavor, La Costeña Salsa de Chipotle brings traditional Mexican heat straight to your plate. Made with real chipotle peppers, this bold sauce adds depth and warmth to everything from tacos to grilled meats. 🌶️ Brand: La Costeña 🌶️ Made with authentic chipotle chiles 🌶️ Smoky, medium heat with a tangy kick 🌶️ Ideal for marinades, tacos, or dipping 🌶️ 140 ml glass bottle. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_f33d7ea5-70be-44bc-b53f-c50a835c4f64.png?v=1750328539', 50, 'My Store', false, false),
  ('CMX-DRIED-CHILIES-CRACKLING-LA-CONSPIRACION', 'Dried chilies crackling, La Conspiración', 'salsas', 33.50, 'Crunch meets heat in this rich and smoky blend, La Conspiración Chicharrón de Mezcla de Chiles Secos combines crispy chicharrón (chili rind cracking) with a handcrafted mix of dried Mexican chilies. It’s bold, intense, and seriously addictive, perfect as a topping, snack, or spicy sidekick. 🌶️ Brand: La Conspiración 🌶️ Handcrafted blend of dried chilies crackling 🌶️ Deep, smoky flavor with a crunchy texture 🌶️ Great with tacos, tostadas, or straight from the jar 🌶️ 250 g glass jar. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_6c833af3-3d69-4102-9293-150f719d8e78.png?v=1750328110', 50, 'My Store', false, false),
  ('CMX-ALEBRIJE-MANGO-AND-HABANERO-JAM-LA-CONSPIRACION', 'Alebrije Mango & Habanero Jam, La Conspiración', 'salsas', 25.50, 'Sweet with a fiery spirit, La Conspiración Alebrije blends ripe mango with the bold kick of habanero chili to create an artisanal jam that’s anything but ordinary. Perfect with cheese boards, grilled meats, or simply spread on warm toast. 🌶️ Brand: La Conspiración 🌶️ Flavor combo: juicy mango + spicy habanero 🌶️ Ideal for savory-sweet pairings 🌶️ Small-batch, Mexican-made goodness 🌶️ 250 g glass jar. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_d212874f-ce6b-494a-a159-72f8f2949827.png?v=1750327556', 50, 'My Store', false, false),
  ('CMX-PINERA-SAUCE-LA-CONSPIRACION', 'Piñera Sauce,La Conspiración', 'salsas', 25.50, 'Sweet meets heat in this tropical sensation, Salsa Piñera blends juicy pineapple with bold habanero for a vibrant salsa that’s fruity, fiery, and unforgettable. Ideal for grilled shrimp, tacos al pastor, or even spooned over cream cheese. 🌶️ Brand: La Conspiración 🌶️ Made with real pineapple &amp; habanero 🌶️ Tropical, tangy, and spicy 🌶️ Delicious on seafood, white meats, or chips 🌶️ 250 g glass jar. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_113fee27-29cc-4704-aea5-98d86dfcb949.png?v=1750326859', 50, 'My Store', false, false),
  ('CMX-BICHOLA-SAUCE-LA-CONSPIRACION', 'Bichola Sauce, La Conspiración', 'salsas', 25.50, 'A smoky-sweet salsa with depth and bold personality, Salsa Bichola combines rich chipotle heat with a surprising twist of hibiscus (jamaica) for a one-of-a-kind flavor. Earthy, tangy, and deliciously addictive. 🌶️ Brand: La Conspiración 🌶️ Made with hibiscus (jamaica) &amp; smoked chipotle 🌶️ Sweet, tangy, and mildly spicy 🌶️ Perfect on grilled meats, tacos al pastor, or roasted veggies 🌶️ 250 g glass jar. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_0dcdc677-6d59-4065-ab3a-cfcf79d45bcc.png?v=1750326182', 50, 'My Store', false, false),
  ('CMX-BICHI-SAUCE-LA-CONSPIRATION', 'Bichi Sauce, La Conspiration', 'salsas', 25.50, 'Creamy, zesty, and undeniably fresh — Salsa Bichi is a smooth blend of serrano chiles, cilantro, and crema that brings a herbaceous heat to your dishes. Perfect for tacos, grilled corn, seafood, or as a dip for chips. 🌶️ Brand: La Conspiración 🌶️ Made with serrano chiles, cilantro &amp; cream 🌶️ Mild heat with rich, creamy texture 🌶️ Great on tacos, tostadas, or veggies 🌶️ 250 g glass jar. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_1b819d58-7136-4702-b6a2-d867ad76a544.png?v=1750324435', 50, 'My Store', false, false),
  ('CMX-MOJITO-GREEN-SAUCE-LA-CONSPIRACION', 'Mojito Green Sauce, La Conspiración', 'salsas', 25.50, 'A refreshingly bold twist on salsa, Salsa Mojito Verde by La Conspiración combines roasted chiles with fresh spearmint for a zesty, herbaceous kick. Bright, slightly smoky, and completely unique, it’s a flavorful topping or marinade for tacos, grilled veggies, seafood, or even salads. 🌿 Brand: La Conspiración 🌿 Made with spearmint &amp; roasted chiles 🌿 Herbal, smoky, and tangy flavor profile 🌿 Perfect for seafood, salads, or chicken 🌿 250 g glass jar. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_9374f533-12f8-447e-89a9-ed53ffc18275.png?v=1750323906', 50, 'My Store', false, false),
  ('CMX-THREE-CHILI-SAUCE-LA-CONSPIRACION', 'Three Chili Sauce, La Conspiración', 'salsas', 25.50, 'Creamy, smoky, and packed with flavor, Salsa Tres Chiles by La Conspiración blends three smoked chili peppers with smooth cream for a rich and bold Mexican sauce. It’s the perfect balance of heat and indulgence, ready to elevate tacos, sandwiches, grilled meats, or even breakfast eggs. 🔥 Brand: La Conspiración 🔥 Made with 3 smoked chili varieties 🔥 Cream-based with a velvety texture 🔥 Great with grilled meats, tacos, or as a dip 🔥 250 g glass jar. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_1691969d-4a69-447e-b3d3-f7a51a7f1238.png?v=1750321783', 50, 'My Store', false, false),
  ('CMX-CHOLULA-HOT-SAUCE', 'Cholula Original Hot Sauce', 'salsas', 20.95, 'A true Mexican classic. Cholula Original Hot Sauce delivers a well-balanced, zesty blend of piquín and arbol peppers with a signature flavor that enhances rather than overpowers. Smooth, smoky, and just the right amount of heat, it’s the go-to bottle for flavor lovers everywhere. 🌶️ Brand: Cholula 🌶️ Iconic wooden cap &amp; authentic recipe 🌶️ Mild-to-medium heat with a smoky finish 🌶️ Great for eggs, tacos, pizza, popcorn &amp; more 🌶️ 150 ml glass bottle. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_d5c866bb-7017-4b15-bef7-38748a9b3416.png?v=1750320898', 50, 'My Store', false, false),
  ('CMX-TAJIN-CHAMOY-HOT-SAUCE', 'Tajín Chamoy Hot Sauce', 'salsas', 33.50, 'A tangy-sweet twist with a mild kick — Tajín Chamoy Sauce brings together fruity chamoy flavor, chili, and lime in a smooth, pourable blend. Perfect for topping fruits, snacks, drinks, or even desserts, it adds a bold, mouthwatering zing that’s hard to resist. 🍑 Brand: Tajín 🍑 Classic chamoy flavor with chili and lime 🍑 Mild heat with sweet &amp; tangy undertones 🍑 Ideal for fruit bowls, gummy candy, mangonadas &amp; rim dips 🍑 455 ml squeeze bottle for easy use. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_bee3bb94-115b-4867-a76b-450f5bf88a1c.png?v=1750320473', 50, 'My Store', false, false),
  ('CMX-VALENTINA-SALSA-PICANTE-YELLOW-LABEL-1LT', 'Valentina Salsa Picante (Original Yellow Label) 1lt', 'salsas', 33.50, 'The flavor you know and love, now in a party-size bottle! Valentina Salsa Picante Original delivers a mild heat with a tangy chili flavor that pairs perfectly with snacks, fruits, chips, soups, and more. This 1-liter bottle is made for true Valentina lovers who don’t want to run out anytime soon. 🌶️ Brand: Valentina 🌶️ Signature Mexican hot sauce, tangy &amp; balanced 🌶️ Mild spice, perfect for all taste levels 🌶️ Great for large gatherings, restaurants, or hot sauce addicts 🌶️ 1-liter bottle, classic yellow label. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_516d9b00-ec5a-4f45-9887-77eedd643717.png?v=1750320334', 50, 'My Store', false, false),
  ('CMX-VALENTINA-SALSA-PICANTE-YELLOW-LABEL', 'Valentina Salsa Picante (Original Yellow Label)', 'salsas', 17.00, 'A beloved classic in every Mexican kitchen, Valentina Salsa Picante Original is famous for its tangy, mild-to-medium chile flavor and smooth texture. It’s not just hot sauce—it’s a way of life. Splash it over popcorn, fruit, soups, chips, eggs, and everything in between! 🌶️ Brand: Valentina 🌶️ Mild to medium heat with tangy chile flavor 🌶️ Versatile and smooth, not overly vinegary 🌶️ Perfect for snacks, soups, and street-style dishes 🌶️ 370 ml plastic bottle, iconic yellow label. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_0a5d2eae-c990-4518-b16e-f4b653d850be.png?v=1750319707', 50, 'My Store', false, false),
  ('CMX-VALENTINA-SALSA-PICANTE-VERY-HOT-BLACK-LABEL', 'Valentina Salsa Picante Very Hot (Black Label)', 'salsas', 15.25, 'Mexico’s cult-favorite hot sauce, now in its extra-hot black-label version! Valentina Salsa Picante “Muy Picante” delivers a thicker, tangy chile-arbol heat that clings to everything from tacos and popcorn to micheladas. 🌶️ Brand: Valentina 🌶️ Extra-hot black label (“Muy Picante”) 🌶️ Tangy chile-arbol flavor with a lingering burn 🌶️ Perfect for tacos, fruit, chips, soups &amp; cocktails 🌶️ 370 ml plastic bottle – pour on the heat! Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_ffbefd28-b5bf-4b1f-8727-28a94de15207.png?v=1750319472', 50, 'My Store', false, false),
  ('CMX-MARISQUERA-BLACK-HOT-SAUCE-EL-YUCATECO', 'Marisquera Black Hot Sauce, El Yucateco', 'salsas', 19.00, 'Bring bold coastal flavor to your dishes with El Yucateco Marisquera Negra Hot Sauce. This smoky, seafood-friendly salsa blends dark spices with tangy heat, creating a rich, savory taste that enhances everything from grilled shrimp to fish tacos. 🌶 Brand: El Yucateco 🌶 Crafted for seafood &amp; coastal dishes 🌶 Dark, smoky flavor with mild heat 🌶 Perfect for ceviche, fish tacos, oysters, and more 🌶 120 ml glass bottle. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_748d248b-c607-4447-82b3-4b321fe8af19.png?v=1750319198', 50, 'My Store', false, false),
  ('CMX-HABANERO-Y-CHILTEPIN-HOT-SAUCE-EL-YUCATECO', 'Habanero y Chiltepín Hot Sauce, El Yucateco', 'salsas', 19.00, 'Feel the fire with the bold, smoky heat of El Yucateco Habanero y Chiltepín Hot Sauce. Infused with the intense, earthy flavor of wild chiltepín peppers and spicy habanero, this sauce packs a punch that chili lovers crave. 🌶 Brand: El Yucateco 🌶 Made with wild chiltepín &amp; habanero peppers 🌶 Deep, smoky heat with earthy undertones 🌶 Ideal for grilled meats, beans, soups, or salsas 🌶 120 ml glass bottle. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_2a04bc9b-e3a3-4a6f-a9e9-e0e4bed28847.png?v=1750318805', 50, 'My Store', false, false),
  ('CMX-HABANERO-AND-PINEAPPLE-SMOKED-HOT-SAUCE-EL-YUCATECO', 'Habanero and Pineapple smoked Hot Sauce, El Yucateco', 'salsas', 19.00, 'Turn up the heat with a tropical twist, El Yucateco Habanero y Piña Asada Hot Sauce combines the fiery kick of habaneros with the smoky-sweet flavor of grilled pineapple. Perfect for BBQs, tacos al pastor, or glazing meats with a bold fruity punch. 🍍 Brand: El Yucateco 🍍 Made with roasted pineapple &amp; habanero peppers 🍍 Sweet, smoky, and spicy all in one 🍍 Great on grilled meats, seafood, or pizza 🍍 120 ml glass bottle. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/2_47cc2db0-745b-495c-84e5-c28c1115fe01.png?v=1750319843', 50, 'My Store', false, false),
  ('CMX-MARISQUERA-RED-HOT-SAUCE-EL-YUCATECO', 'Marisquera Red Hot Sauce, El Yucateco', 'salsas', 19.00, 'Crafted especially for seafood lovers, El Yucateco Marisquera Roja Hot Sauce is a zesty, bold blend designed to elevate shrimp, oysters, ceviche, and more. With its tangy flavor and subtle heat, this sauce brings a splash of the Mexican coast to every bite. 🦐 Brand: El Yucateco 🦐 Ideal for seafood, ceviche, and cocktails 🦐 Balanced with spice, tang, and a hint of citrus 🦐 A coastal favorite with authentic flavor 🦐 150 ml glass bottle. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_86133fb5-08b4-41d7-9937-ad964cf536c8.png?v=1750317981', 50, 'My Store', false, false),
  ('CMX-HABANERO-ANF-COFFEE-HOT-SAUCE-EL-YUCATECO', 'Habanero anf Coffee Hot Sauce, El Yucateco', 'salsas', 19.00, 'A bold blend for true flavor seekers — El Yucateco Habanero y Café Hot Sauce fuses the smoky heat of habanero with the rich depth of coffee. A unique, slightly sweet and roasty sauce that adds character to everything from grilled meats to savory breakfast plates. 🌶️ Brand: El Yucateco 🌶️ Made with habanero chili and coffee 🌶️ Smoky, earthy, and mildly sweet 🌶️ Ideal for grilled dishes, eggs, or BBQ marinades 🌶️ 120 ml glass bottle. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_5805709d-c389-43a4-9b29-82078cbda1c6.png?v=1750317613', 50, 'My Store', false, false),
  ('CMX-HABANERO-AND-GHOST-CHILI-HOT-SAUCE-EL-YUCATECO', 'Habanero & Ghost Chili Hot Sauce, El Yucateco', 'salsas', 19.00, 'Warning: This one’s not for the faint of tongue ! 🌶💀 El Yucateco combines the fierce heat of habanero peppers with the fiery intensity of ghost chilies to create a hot sauce that delivers a slow burn and bold flavor in every drop. Perfect for those who crave extreme heat with character , this sauce amps up tacos, wings, soups, or even cocktails. If you dare, try it on your eggs for breakfast and see how your day starts 🔥 ✅ Made in Mexico ✅ No artificial colors ✅ Heat Level: 🌶🌶🌶🌶 (EXTREME) Net Weight: 120ml. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_6a6d11fd-de8b-44b2-9829-4a74103e4e9a.png?v=1750316980', 50, 'My Store', false, false),
  ('3', 'Habanero Sauce Sampler, La Meridana', 'salsas', 42.00, 'Spice up your kitchen with authentic Mexican heat! 🇲🇽 This boxed sampler from La Meridana brings together four unique habanero hot sauces , each made with real fruit, bold spices, and zero compromises. 🔥 Inside the box: 🍑 Papaya Habanero – Sweet heat with a tropical finish 🥭 Mango Habanero – Fruity fire that dances on the tongue 🌿 Green Habanero – Zesty, fresh, and slightly herbal 🌶 Red Habanero – The classic kick with full chili flavor 💡 Perfect for gifting or sampling – whether you’re new to hot sauce or already addicted. ✔️ Vegan · Gluten-Free · Made in Mexico · 4 x 150 ml bottles. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_3970489d-efca-4246-a4a7-62d2dc17d667.png?v=1750315369', 50, 'My Store', false, false),
  ('CMX-HOT-HABANERO-SAUCE-SAMPLER-LA-MERIDANA', 'Hot Habanero Sauce Sampler Pack, La Meridana', 'salsas', 30.00, 'Taste the full spectrum of Mexican heat with this vibrant sampler pack from La Meridana . Whether you''re gifting or just can’t choose one favorite, this set brings the perfect mix of smoky, fruity, and fiery flavors straight from Mexico. 🔥 Includes 4 x 50 ml bottles: 🌶 Papaya Habanero – Fruity sweetness meets tropical fire 🌶 Mango Habanero – A juicy twist with bold spice 🌶 Green Habanero – Zesty, herbaceous and sharp 🌶 Red Habanero – Classic, fiery and full-bodied 🎁 Perfect for gifting, sampling, or spicing up every meal. 💯 Made in Mexico. 100% authentic. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_6e48c1d5-e121-45a6-9784-1cfa01220727.png?v=1750314363', 50, 'My Store', false, false),
  ('CMX-MANGO-HABANERO-HOT-SAUCE-LA-MERIDANA', 'Mango Habanero Hot Sauce, La Meridana', 'salsas', 19.50, 'Tropical sweetness with a fiery twist — La Meridana Mango Habanero Hot Sauce blends juicy mango with bold habanero heat for a sauce that’s bright, balanced, and totally addictive. Perfect on tacos, wings, or even as a dipping sauce. 🥭 Brand: La Meridana 🥭 Made with real mango &amp; habanero peppers 🥭 Sweet upfront with a spicy finish 🥭 Great for tacos, grilled meats, or mango salsas 🥭 150 ml glass bottle. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_0e8d9f52-d84d-4a2f-b51a-f39feed53cd7.png?v=1750313639', 50, 'My Store', false, false),
  ('CMX-PAPAYA-HABANERO-HOT-SAUCE-LA-MERIDANA', 'Papaya Habanero Hot Sauce, La Meridana', 'salsas', 19.00, 'Sweet, tropical papaya meets fiery habanero in this unique, flavor-packed hot sauce from La Meridana . The perfect balance of fruity and spicy, it’s a delicious addition to seafood, grilled chicken, tacos, or even drizzled on fresh fruit. 🌶️ Brand: La Meridana 🌶️ Made with real papaya and habanero chiles 🌶️ Bright, fruity flavor with a bold kick 🌶️ Great on fish, chicken, fruit, or even salad dressings 🌶️ 150 ml glass bottle. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_028e1f19-b3fd-4857-8ff4-a492d6a1e480.png?v=1750313505', 50, 'My Store', false, false),
  ('CMX-CHIPOTLE-AGAVE-HOT-SAUCE-LA-MERIDANA', 'Chipotle Agave Hot Sauce, La Meridana', 'salsas', 9.00, 'Smoky meets sweet in this rich and flavorful Chipotle Agave Hot Sauce by La Meridana. Made with smoked chipotle peppers and balanced with smooth agave syrup, it’s perfect for those who love a deep, savory heat with a hint of sweetness. 🌶️ Brand: La Meridana 🌶️ Made with smoked chipotle chiles &amp; natural agave 🌶️ Mild to medium heat with smoky-sweet flavor 🌶️ Great for marinades, burgers, grilled veggies &amp; tacos 🌶️ 150 ml glass bottle. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_285fc47a-44ef-4f06-b5fe-74229c17f90e.png?v=1750312691', 50, 'My Store', false, false),
  ('CMX-GREEN-HABANERO-HOT-SAUCE', 'Green Habanero Hot Sauce', 'salsas', 19.00, 'Bright, zesty, and full of heat, La Meridana Green Habanero Hot Sauce delivers a fresh punch of flavor with every drop. Made from green habanero chiles, this sauce brings vibrant spice to tacos, ceviches, eggs, and more. 🌶️ Brand: La Meridana 🌶️ Made with fresh green habanero peppers 🌶️ Sharp, citrusy flavor with bold heat 🌶️ Perfect for seafood, tacos, breakfast &amp; more 🌶️ 5 fl oz (150 ml) glass bottle. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/GreenHabanero_1.png?v=1750281392', 50, 'My Store', false, false),
  ('CMX-RED-HABANERO-HOT-SAUCE-LA-MERIDANA', 'Red Habanero Hot Sauce, La Meridana', 'salsas', 19.00, 'Bring the fire with La Meridana Red Habanero Hot Sauce , a bold, fiery classic made with authentic Mexican red habanero peppers. This vibrant sauce is perfect for heat seekers who love balanced spice with a touch of citrusy brightness. 🌶️ Brand: La Meridana 🌶️ Made with real red habanero chiles 🌶️ Intense heat with fresh, tangy flavor 🌶️ Delicious on tacos, eggs, grilled meats, and more 🌶️ 5 fl oz (150 ml) glass bottle. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/RedHabanero.png?v=1750280916', 50, 'My Store', false, false),
  ('CMX-SMOKED-HABANERO-HOT-SAUCE-LA-MERIDANA', 'Smoked Habanero Hot Sauce, La Meridana', 'salsas', 19.00, 'Turn up the heat with La Meridana Smoked Habanero Hot Sauce , a fiery blend of authentic Mexican habaneros and rich smoky flavor. Crafted with love and tradition, this small-batch hot sauce adds the perfect bold kick to tacos, grilled meats, eggs, and more. 🌶️ Brand: La Meridana 🌶️ Made with smoked habanero peppers 🌶️ Deep, smoky heat with a smooth finish 🌶️ Ideal for everyday use, just a few drops pack serious flavor 🌶️ 5 fl oz (150 ml) glass bottle. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/1_a5980940-b181-4d30-ad57-c03362451976.png?v=1750280647', 50, 'My Store', false, false),
  ('CMX-LUCAS-MUECAS-MANGO-SPICY-MANGO-LOLLIPOP-WITH-CHILI-POWDE', 'Lucas Muecas Mango (Spicy Mango Lollipop with Chili Powder)', 'snacks', 39.00, 'A sweet and spicy treat with a tropical twist! Lucas Muecas Mango combines a mango-flavored lollipop with tangy chili powder for dipping fun. Dip, lick, repeat, this is Mexican candy the way it’s meant to be: bold and addictive. 🌶️ Brand: Lucas 🌶️ Mango-flavored lollipop with chili powder dip 🌶️ Sweet, sour, and spicy flavor combo 🌶️ Includes 10 pieces (24 g each) 🌶️ Net weight: 240 g. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/LucasMuecasMango.png?v=1750279231', 50, 'My Store', false, false),
  ('CMX-PELON-PELO-RICO-TAMARIND', 'Pelon Pelo Rico Tamarind', 'snacks', 38.00, 'A classic favorite with a fun twist! Pelon Pelo Rico Tamarindo is a tangy, spicy tamarind-flavored candy that you push up through a soft, squeezable container—creating the signature “hair” effect. Sweet, sour, and seriously fun to eat! 🌶️ Brand: Pelon Pelo Rico 🌶️ Tamarind-flavored candy with a touch of chili 🌶️ Soft texture and unique push-up dispenser 🌶️ Includes 12 individual containers (30 g each) 🌶️ Total net weight: 360 g. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/pelonpelorico_1.png?v=1750278719', 50, 'My Store', false, false),
  ('8', 'Pulparindo Mango (Tamarind Candy with Mango Flavor)', 'snacks', 39.00, 'The perfect twist on a Mexican favorite! Pulparindo Mango blends the classic sweet-sour-spicy tamarind candy with a tropical mango kick. Made from natural tamarind pulp, it’s chewy, tangy, and full of bold flavor in every bite. 🥭 Brand: De la Rosa 🥭 Tamarind candy with chili, salt, and natural mango flavor 🥭 Sweet, sour, spicy, and tropical, all in one! 🥭 Includes 20 individually wrapped pieces 🥭 Net weight: 280 g. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/PulparindoMangoFront.png?v=1750277434', 50, 'My Store', false, false),
  ('0', 'Mazapan Original, De la Rosa', 'snacks', 21.90, 'A true classic! De la Rosa Mazapán is Mexico’s beloved peanut candy, known for its soft, crumbly texture and rich nutty flavor. Made from crushed peanuts and sugar, it melts in your mouth and brings sweet nostalgia with every bite. 🥜 Brand: De la Rosa 🥜 Original peanut marzipan candy since 1950 🥜 Soft, crumbly texture with bold peanut flavor 🥜 Contains 12 individually wrapped pieces 🥜 Net weight: 336 g. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/mazapanfront.png?v=1750276948', 50, 'My Store', false, false),
  ('CMX-LUCAS-MUECAS-CHAMOY', 'Lucas Muecas Chamoy', 'snacks', 39.00, 'Sweet, sour, and irresistibly spicy! Lucas Muecas Chamoy is a classic Mexican lollipop dipped in tangy chamoy powder. It’s the perfect mix of flavors that dance on your taste buds with every lick. Fun to eat and packed with flavor. 🌶️ Brand: Lucas 🌶️ Chamoy-flavored lollipop with tangy chili powder 🌶️ Unique push-up style candy you can dip again and again 🌶️ Includes 10 individual pieces , great for sharing or party favors 🌶️ A popular Mexican treat for spicy candy lovers. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/LucasMuecasfront.png?v=1750276059', 50, 'My Store', false, false),
  ('CMX-PALEBOLA-TAMA-ROCA-TAMARIND-CANDY', 'Palebola Tama-Roca Tamarind Candy', 'snacks', 43.00, 'Spicy, salty, and sweet, Palebola Tama-Roca is an iconic Mexican tamarind candy that packs a punch! Made with natural tamarind, chili, and salt, it’s a bold treat for those who crave intense, tangy flavors. A nostalgic favorite since 1975. 🌶️ Brand: Palebola Tama-Roca 🌶️ Natural tamarind candy with chili and salt 🌶️ A true Mexican classic, spicy, sour, and addictive! 🌶️ Contains 12 individually packed pieces 🌶️ Net weight: 720 g. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/Palebolafront.png?v=1750275118', 50, 'My Store', false, false),
  ('CMX-BARRITAS-STRAWBERRY-MARINELA-2', 'Barritas Strawberry,Marinela', 'snacks', 29.50, 'Soft, fruity, and deliciously nostalgic, Marinela Barritas Fresa are tender cookie bars filled with a sweet strawberry jam center. A classic Mexican snack perfect for school lunches, coffee breaks, or an anytime treat. 🍓 Brand: Marinela 🍓 Soft-baked bars with real strawberry filling 🍓 Each box contains 12 individually wrapped bars 🍓 Great for on-the-go snacking or sharing 🍓 Net weight: 402 g. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/barritasback.png?v=1750273323', 50, 'My Store', false, false),
  ('CMX-WHOLE-PASILLA-CHILI-EL-FRESNO-2', 'Whole Pasilla Chili, El Fresno', null, 16.00, 'Bring authentic flavor to your kitchen with El Fresno Whole Dried Pasilla Chilies . Known for their dark color and rich, mildly spicy profile, these chilies are perfect for creating depth in traditional Mexican dishes like moles, sauces, and soups. 🌶️ Brand: El Fresno 🌶️ 100% whole dried pasilla chiles 🌶️ Mild heat with a deep, raisin-like sweetness 🌶️ Ideal for moles, enchilada sauces, and slow-cooked recipes 🌶️ 100 g pack, great for home cooks exploring Mexican cuisine', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/ChiliPasilla1.png?v=1750235329', 50, 'My Store', false, false),
  ('CMX-GUAJILLO-CHILI-POWDER-XATZE', 'Guajillo Chili Powder, Xatze', 'chiles', 42.50, 'Smooth, smoky, and slightly sweet, Xatze Ground Guajillo Chili adds authentic depth to your dishes. Made from dried guajillo peppers, this versatile chili powder enhances sauces, soups, stews, and marinades with a warm, rich flavor and gentle heat. 🌶️ Brand: Xatze 🌶️ 100% natural ground guajillo chiles 🌶️ Mild-to-medium heat with a subtle fruity taste 🌶️ Perfect for salsas, adobo sauces, moles, and slow-cooked meals 🌶️ 550 g bottle – great for home kitchens and professional use. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/ChiliGuajillo_1.png?v=1750231656', 50, 'My Store', false, false),
  ('CMX-ARBOL-CHILI-POWDER-XATZE', 'Árbol Chili Powder, Xatze', 'chiles', 42.50, 'Bring the heat with Xatze Ground Chile de Árbol , a bold and fiery chili powder made from dried árbol peppers. Known for their vibrant color and spicy kick, this finely ground chili is perfect for adding intense flavor to salsas, sauces, meat rubs, and more. 🌶️ Brand: Xatze 🌶️ 100% natural ground chile de árbol 🌶️ Hot and sharp flavor with a hint of nuttiness 🌶️ Great for spicy salsas, marinades, and dry rubs 🌶️ 550 g bottle, ideal for both home cooks and professional kitchens. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/ChiliArbol_1.png?v=1750231101', 50, 'My Store', false, false),
  ('CMX-ANCHO-CHILI-POWDER-XATZE', 'Ancho Chili Powder, Xatze', 'chiles', 42.50, 'Add a rich, smoky flavor to your favorite dishes with Xatze Ground Ancho Chili . Made from dried poblano peppers, this deep red powder brings mild heat and a subtle sweetness to everything from rubs and marinades to soups and stews. 🌶️ Brand: Xatze 🌶️ 100% natural ground ancho chiles (dried poblano peppers) 🌶️ Mild heat with a sweet, smoky flavor 🌶️ Ideal for spice blends, BBQ rubs, sauces, and slow-cooked meals 🌶️ 550g bottle, perfect for kitchens, restaurants, or food lovers. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/AnchoMolidoSquare.png?v=1750230378', 50, 'My Store', false, false),
  ('CMX-CHILE-ANCHO-150G-WHOLE-DRIED-CHILIES', 'Chile Ancho 150G (Whole Dried Chilies), INTERMEX', 'chiles', 20.00, 'Deep, smoky, and slightly sweet, Whole Dried Ancho Chilies are a pantry essential for authentic Mexican cuisine. These dried poblano peppers bring complex flavor and mild heat to your sauces, stews, marinades, and moles. 🌶️ Brand: Intermex 🌶️ 100% whole dried ancho chiles (sun-dried poblanos) 🌶️ Rich, earthy flavor with a hint of sweetness 🌶️ Ideal for rehydrating and blending into traditional Mexican recipes 🌶️ 150 g. Available from Corner Mex for delivery in Dubai, Abu Dhabi and across the UAE.', 'https://cdn.shopify.com/s/files/1/0642/6725/5904/files/Screenshot_2026-04-18_100837.png?v=1776492582', 50, 'My Store', false, false)
), checks as (
  select
    count(*) filter (where nullif(trim(sku), '') is null) as empty_sku_count,
    count(*) filter (where nullif(trim(name), '') is null) as empty_name_count,
    (select count(*) from (select sku from incoming group by sku having count(*) > 1) d) as duplicate_sku_count
  from incoming
)
select * from checks;

-- Founder/operator must verify checks are all zero before running the upsert below.

insert into public.products (
  sku, name, category, price_aed, description, image_url, stock, supplier, active, b2b_available
)
select
  sku, name, category, price_aed, description, image_url, stock, supplier, active, b2b_available
from incoming
where nullif(trim(sku), '') is not null
  and nullif(trim(name), '') is not null
on conflict (sku) do update set
  name = excluded.name,
  category = coalesce(public.products.category, excluded.category),
  price_aed = coalesce(public.products.price_aed, excluded.price_aed),
  description = coalesce(public.products.description, excluded.description),
  image_url = coalesce(public.products.image_url, excluded.image_url),
  stock = case when public.products.stock is null or public.products.stock = 0 then excluded.stock else public.products.stock end,
  supplier = coalesce(public.products.supplier, excluded.supplier),
  active = public.products.active and excluded.active,
  b2b_available = public.products.b2b_available or excluded.b2b_available,
  updated_at = now();

select count(*) as total_products from public.products;
select count(*) as products_with_price from public.products where price_aed is not null;
select count(*) as products_with_image from public.products where image_url is not null and trim(image_url) <> '';
select count(*) as products_with_stock_50 from public.products where stock = 50;
select sku, count(*) from public.products group by sku having count(*) > 1;

rollback;
-- Replace rollback with commit only after founder review and successful preflight checks.
